CREATE PROCEDURE SearchAllTables
    @TableName NVARCHAR(128),
    @SearchValue NVARCHAR(255)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @SQL NVARCHAR(MAX);

    -- Update table
    SET @SQL = 'UPDATE ' + QUOTENAME(@TableName) + ' SET Status = ''Updated'' WHERE ColumnName LIKE @SearchValue';
    EXEC sp_executesql @SQL, N'@SearchValue NVARCHAR(255)', @SearchValue;

    -- Insert into another table
    SET @SQL = 'INSERT INTO AnotherTable (Column1, Column2) SELECT Column1, Column2 FROM ' + QUOTENAME(@TableName) + ' WHERE ColumnName LIKE @SearchValue';
    EXEC sp_executesql @SQL, N'@SearchValue NVARCHAR(255)', @SearchValue;

    -- Delete from another table
    SET @SQL = 'DELETE FROM YetAnotherTable WHERE Column1 IN (SELECT Column1 FROM ' + QUOTENAME(@TableName) + ' WHERE ColumnName LIKE @SearchValue)';
    EXEC sp_executesql @SQL, N'@SearchValue NVARCHAR(255)', @SearchValue;

    -- Select from a table
    SET @SQL = 'SELECT * FROM ' + QUOTENAME(@TableName) + ' WHERE ColumnName LIKE @SearchValue';
    EXEC sp_executesql @SQL, N'@SearchValue NVARCHAR(255)', @SearchValue;
END
